('starx-digital', 'STARX DIGITAL', 'High-Performance Web Architecture & Digital Commerce', 'Specialized in corporate websites, high-conversion landing pages, e-commerce platforms, and progressive web apps.', 'Web & E-Commerce', 'To eliminate slow, bloated, generic web templates and deliver hand-crafted, high-converting digital storefronts and corporate websites for market-leading brands.', 'STARX DIGITAL delivers modern web presences that combine cinematic design with rock-solid corporate typography, sub-second response times, and measurable commercial conversion.', '[{"title":"Business & Corporate Websites","description":"Bespoke digital headquarters that build trust."}]'::jsonb, '["Custom responsive design system","Full Next.js / TypeScript source code"]'::jsonb, '["Next.js 16","React 19","TypeScript","Tailwind CSS v4"]'::jsonb, 'published', 1, 'STARX DIGITAL — Web Architecture & Digital Commerce', 'High-performance web architecture, corporate websites, and e-commerce platforms.', NOW()),
('starx-systems', 'STARX SYSTEMS', 'Custom Software, Enterprise Dashboards & Microservices', 'Specialized in bespoke business operating systems, internal workflow engines, and distributed API gateways.', 'Systems & Cloud', 'To architect secure, scalable, fault-tolerant software backends that automate complex operations.', 'STARX SYSTEMS engineers robust software architectures that power business operations with sub-second data synchronization.', '[{"title":"Bespoke Business Software","description":"Tailored workflow platforms replacing fragmented spreadsheets."}]'::jsonb, '["Custom database schema and migrations","Zero-trust authorization matrix"]'::jsonb, '["Next.js","PostgreSQL","Supabase","Redis","Docker"]'::jsonb, 'published', 2, 'STARX SYSTEMS — Enterprise Software & Cloud Architecture', 'Custom software engineering, high-concurrency microservices, and enterprise dashboards.', NOW()),
('starx-ai-solutions', 'STARX AI SOLUTIONS', 'Applied AI, Intelligent Workflows & Enterprise RAG', 'Specialized in domain-specific Retrieval-Augmented Generation, fine-tuned agentic pipelines, and computer vision.', 'Applied AI', 'To transition enterprises from experimental AI chat toys to deterministic, secure business automations.', 'STARX AI SOLUTIONS bridges cutting-edge machine learning with enterprise software engineering.', '[{"title":"Enterprise RAG Pipelines","description":"Deterministic semantic retrieval over proprietary documents."}]'::jsonb, '["Grounded vector embedding pipelines","Strict hallucination guardrails"]'::jsonb, '["Python","LangChain","pgvector","Next.js"]'::jsonb, 'published', 3, 'STARX AI SOLUTIONS — Enterprise AI & RAG Pipelines', 'Applied artificial intelligence, grounded RAG pipelines, and agentic workflows.', NOW())
